register_rest_route('surfside/v1','/events',array('methods'=>WP_REST_Server::READABLE,'callback'=>'surfside_tools_mobile_api_events','permission_callback'=>'__return_true','args'=>array('start'=>array('sanitize_callback'=>'sanitize_text_field','validate_callback'=>'surfside_tools_mobile_api_validate_date'),'end'=>array('sanitize_callback'=>'sanitize_text_field','validate_callback'=>'surfside_tools_mobile_api_validate_date'),'limit'=>array('default'=>50,'sanitize_callback'=>'absint','validate_callback'=>function($value){return(int)$value>=1&&(int)$value<=100;}))));
register_rest_route('surfside/v1','/contact',array('methods'=>WP_REST_Server::CREATABLE,'callback'=>'surfside_tools_mobile_api_contact','permission_callback'=>'__return_true'));
